edits.before:
this._setupDismiss()

// Set initial value if input has a value
if (this._isInput && this._element.value) {
  this._parseInputValue()
}

edits.after:
this._setupDismiss()

// Allow Tab key to move focus out of the date input (VCP inputMode blocks Tab)
if (this._isInput) {
  this._element.addEventListener('keydown', (event) => {
    if (event.key === 'Tab') {
      event.stopPropagation()
    }
  }, true) // capture phase to intercept before VCP's listener
}

// Set initial value if input has a value
if (this._isInput && this._element.value) {
  this._parseInputValue()
}
